use crate::workstation_process::{OwnedProcess,LocalProcessSpec,ConsoleSize};
use std::{thread,time::{Duration,Instant}};
fn spec()->LocalProcessSpec{let environment=["SystemRoot","WINDIR","PATH","TEMP","TMP"].into_iter().filter_map(|k|std::env::var_os(k).map(|v|(k.into(),v))).collect();LocalProcessSpec{executable:std::env::var_os("VIVIM_PTY_FIXTURE_EXE").unwrap().into(),workspace:std::env::current_dir().unwrap(),args:vec![],environment,tail_bytes:65536}}
fn marker(p:&mut OwnedProcess,s:&str){let t=Instant::now();loop{let(out,_)=p.output().unwrap();let observed=String::from_utf8_lossy(&out.bytes);if observed.contains(s){return}assert!(p.poll().unwrap().is_none(),"early exit: {observed}");assert!(t.elapsed()<Duration::from_secs(8),"missing {s}: {observed}");thread::sleep(Duration::from_millis(20));}}
fn closed(p:&OwnedProcess)->String{let t=Instant::now();loop{let(out,err)=p.output().unwrap();if out.closed&&err.closed{assert!(!out.read_failed&&!err.read_failed);return String::from_utf8_lossy(&out.bytes).into_owned()}assert!(t.elapsed()<Duration::from_secs(5));thread::sleep(Duration::from_millis(20));}}
#[test]fn owned_standard_streams_resize_and_exit(){let mut p=OwnedProcess::start_console(spec(),ConsoleSize{columns:80,rows:24}).unwrap();marker(&mut p,"VIVIM_PTY_READY");p.resize_console(ConsoleSize{columns:100,rows:30}).unwrap();p.send_input(b"native-roundtrip\r".to_vec()).unwrap();marker(&mut p,"VIVIM_PTY_ACK:native-roundtrip");p.send_input(b"exit\r".to_vec()).unwrap();assert!(p.wait_for(Duration::from_secs(8)).unwrap().unwrap().success());let text=closed(&p);assert!(text.contains("VIVIM_PTY_SIZE=100x30"),"{text}");assert!(text.contains("VIVIM_PTY_BYE"));println!("OWNED_CONPTY_STDIO_RESIZE_EXIT_OK");}
#[test]fn owned_console_cancel_releases_streams_without_affecting_other_job(){let mut a=OwnedProcess::start_console(spec(),ConsoleSize{columns:80,rows:24}).unwrap();marker(&mut a,"VIVIM_PTY_READY");let mut b=OwnedProcess::start_console(spec(),ConsoleSize{columns:80,rows:24}).unwrap();marker(&mut b,"VIVIM_PTY_READY");assert!(!a.cancel().unwrap().success());closed(&a);assert!(b.poll().unwrap().is_none());b.cancel().unwrap();closed(&b);println!("OWNED_CONPTY_CANCEL_OK");}
